from fractions import Fraction

def calculate_SA(K):
    S_A = Fraction(0)
    for n in range(1, K):
        # Numerator: K^n
        numerator = K**n

        # Denominator: (K+1) * (K+2) * ... * (K+n)
        denominator = 1
        for j in range(1, n + 1):
            denominator *= (K + j)

        S_A += Fraction(numerator, denominator)
    return S_A

K_values = [3, 4, 5]
results = {}
for K in K_values:
    results[K] = calculate_SA(K)

for K, S_A in results.items():
    print(f"K={K}: S_A = {S_A}")

